"use strict";
// Read-only watcher, sent on stdin into the existing CI job container.
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const cp = require("node:child_process");
const [root, expectedCommit] = process.argv.slice(2);
if (!path.isAbsolute(root) || !/^[a-f0-9]{40}$/.test(expectedCommit)) process.exit(2);
const started = Date.now();
const filename = path.join(root, "docs/checks/phase-08.json");
const digest = data => crypto.createHash("sha256").update(data).digest("hex");
const git = arguments_ => cp.execFileSync("git", ["-c", `safe.directory=${root}`, "-C", root, ...arguments_],
                                   { encoding: "utf8", timeout: 5000 }).trim();
const commit = () => git(["rev-parse", "HEAD"]);
if (commit() !== expectedCommit) process.exit(3);
const initial = fs.existsSync(filename) ? digest(fs.readFileSync(filename)) : null;
let emittedParent = null;
const initialChildren = new Map();
for (const name of fs.readdirSync(path.join(root, "docs/checks"))) {
  if (/^phase-08[^/]*\.json$/.test(name)) {
    const full = path.join(root, "docs/checks", name);
    const info = fs.lstatSync(full);
    if (info.isFile() && info.size <= 64 * 1024 * 1024)
      initialChildren.set(`docs/checks/${name}`, digest(fs.readFileSync(full)));
  }
}
function boundedRead(relative) {
  if (!/^docs\/checks\/phase-08[^/]*\.json$/.test(relative)) throw new Error("Unexpected report path");
  const full = path.join(root, relative);
  const info = fs.lstatSync(full);
  if (!info.isFile() || info.size > 64 * 1024 * 1024) throw new Error("Report not bounded");
  const content = fs.readFileSync(full);
  return { path: relative, sha256: digest(content), report: JSON.parse(content) };
}
const timer = setInterval(() => {
  if (Date.now() - started > 3 * 60 * 60 * 1000) process.exit(4);
  try {
    const parent = boundedRead("docs/checks/phase-08.json");
    if (parent.sha256 === initial || parent.report.phase !== 8 ||
        !Array.isArray(parent.report.checks) ||
        !(Date.parse(parent.report.checked_at) >= started)) return;
    // Preserve the parent immediately; job cleanup may remove the container
    // before the optional child-report and source-inventory bundle finishes.
    if (emittedParent !== parent.sha256) {
      process.stdout.write(JSON.stringify({
        kind: "phase_report", schemaVersion: 1,
        capturedAt: new Date().toISOString(), sourceCommit: commit(),
        watcherStartedAt: new Date(started).toISOString(), parent,
      }) + "\n");
      emittedParent = parent.sha256;
    }
    const reports = [];
    for (const check of parent.report.checks) {
      const index = check.command.indexOf("--output");
      if (index === -1) continue;
      const relative = check.command[index + 1];
      if (/^docs\/checks\/phase-08[^/]*\.json$/.test(relative)) {
        const item = boundedRead(relative);
        item.changedSinceWatcherStarted = initialChildren.get(relative) !== item.sha256;
        reports.push(item);
      }
    }
    const after = commit();
    const sourceFiles = [];
    const names = [...new Set(git(["ls-files", "--cached", "--others", "--exclude-standard", "-z"])
      .split("\0").filter(Boolean))].sort();
    let sourceBytes = 0;
    for (const name of names) {
      if (name === "docs/phase-status.json" || name.startsWith("docs/checks/") ||
          name.startsWith("docs/reviews/")) continue;
      const full = path.resolve(root, name);
      if (!full.startsWith(root + path.sep)) throw new Error("Invalid source path");
      const info = fs.lstatSync(full);
      sourceBytes += info.size;
      if (sourceFiles.length >= 32768 || info.size > 64 * 1024 * 1024 ||
          sourceBytes > 256 * 1024 * 1024) throw new Error("Source bound exceeded");
      sourceFiles.push(info.isFile() ? {path: name, sha256: digest(fs.readFileSync(full)), bytes: info.size}
                                   : {path: name, regularFile: false});
    }
    const result = {
      kind: "phase_bundle",
      schemaVersion: 1,
      capturedAt: new Date().toISOString(),
      watcherStartedAt: new Date(started).toISOString(),
      method: "Read-only watcher in the existing Forgejo job container through configured kubectl and Docker access.",
      sourceCommit: expectedCommit, commitUnchanged: after === expectedCommit,
      parent, reports, sourceFiles,
      limits: ["Reads generated credential-free reports without changing the job filesystem or environment.",
               "The phase report and job completion are independently confirmed against Forgejo run metadata."]
    };
    clearInterval(timer);
    process.stdout.write(JSON.stringify(result) + "\n");
  } catch (_) {
    // A report can be observed during its ordinary write; wait for valid JSON.
  }
}, 250);
